const cfg = $json || {};
if (!cfg.locationId) throw new Error('Missing Config.locationId');
if (!cfg.apiKey) throw new Error('Missing Config.apiKey');

const baseUrl = String(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const dryRun = !!cfg.dryRun;

const headers = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest({ method, path, body }) {
  const options = {
    method,
    url: `${baseUrl}${path}`,
    headers,
    json: true,
  };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
      requestBody: body,
    };
  }
}

function getArrayPayload(obj) {
  if (Array.isArray(obj)) return obj;
  if (Array.isArray(obj?.customFields)) return obj.customFields;
  if (Array.isArray(obj?.data?.customFields)) return obj.data.customFields;
  if (Array.isArray(obj?.data)) return obj.data;
  return [];
}

const targetName = 'Batch_Upload';
const requiredType = 'TEXT';

const cfRes = await apiRequest.call(this, { method: 'GET', path: `/locations/${cfg.locationId}/customFields?model=contact` });
if (!cfRes.ok) throw new Error(`Failed to fetch custom fields: ${cfRes.status} ${JSON.stringify(cfRes.data)}`);

let customFields = getArrayPayload(cfRes.data);
let field = customFields.find((f) => (f?.name || '').trim() === targetName);

if (field) {
  const dt = String(field?.dataType || field?.fieldType || field?.type || '').toUpperCase();
  if (!['TEXT', 'LARGE_TEXT'].includes(dt)) {
    throw new Error(`CONFLICT: ${targetName} exists with type ${dt}, required ${requiredType}`);
  }
  return [{ json: { ok: true, dryRun, fieldName: targetName, fieldId: field.id || null, type: dt, action: 'Reused' } }];
}

if (dryRun) {
  return [{ json: { ok: true, dryRun, fieldName: targetName, fieldId: null, type: requiredType, action: 'Planned Create (dryRun)' } }];
}

const createBodies = [
  { name: targetName, model: 'contact', dataType: 'TEXT' },
  { name: targetName, objectKey: 'contact', dataType: 'TEXT' },
];

let created = null;
let lastErr = null;
for (const body of createBodies) {
  const r = await apiRequest.call(this, { method: 'POST', path: `/locations/${cfg.locationId}/customFields`, body });
  if (r.ok) { created = r.data; break; }
  lastErr = r;
}
if (!created) throw new Error(`Failed to create ${targetName}: ${JSON.stringify(lastErr)}`);

const verifyRes = await apiRequest.call(this, { method: 'GET', path: `/locations/${cfg.locationId}/customFields?model=contact` });
if (!verifyRes.ok) throw new Error(`Created ${targetName} but verify failed: ${verifyRes.status} ${JSON.stringify(verifyRes.data)}`);
customFields = getArrayPayload(verifyRes.data);
field = customFields.find((f) => (f?.name || '').trim() === targetName);

return [{ json: { ok: true, dryRun, fieldName: targetName, fieldId: field?.id || null, type: field?.dataType || requiredType, action: 'Created' } }];
